import React, { useState } from 'react';
import { Search, Filter, ChevronRight, Sparkles, ShieldCheck, Calendar, Phone, Mail, MapPin, UserCheck, ChevronDown, MoreHorizontal } from 'lucide-react';

const attorneys = [
  {
    id: 1,
    name: 'Alex Mercer',
    title: 'Partner & Chief Counsel',
    area: 'Corporate & M&A',
    bio: 'Alex is a seasoned corporate lawyer with over 15 years of experience. He specializes in mergers, acquisitions, and venture capital investments.',
    profile: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400&q=80',
    office: 'New York',
    rate: '$1800/h',
    badge: 'Expert',
    verified: true
  },
  {
    id: 2,
    name: 'Jordan Harper',
    title: 'Senior Associate',
    area: 'Intellectual Property & Patents',
    bio: 'Jordan handles IP portfolios for startups and scale-ups, ensuring robust patent filings and trademark protections.',
    profile: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=400&q=80',
    office: 'San Francisco',
    rate: '$1200/h',
    badge: 'IP Specialist',
    verified: true
  },
  {
    id: 3,
    name: 'Sarah Reeves',
    title: 'Counsel',
    area: 'Employment Law & HR',
    bio: 'Sarah advises clients on compliance with labor laws, drafts employee handbooks, and handles EEOC matters.',
    profile: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400&q=80',
    office: 'Chicago',
    rate: '$1100/h',
    badge: 'Compliance Expert',
    verified: true
  }
];

export default function Attorneys() {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('All');
  const [sortedBy, setSortedBy] = useState('name');
  const [asc, setAsc] = useState(true);

  const handleFilter = (e) => {
    setFilter(e.target.value);
  };

  const handleSort = (field) => {
    setSortedBy(field);
    setAsc(!asc);
  };

  const filteredAttorneys = attorneys.filter((att) => {
    const matchesSearch = att.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filter === 'All' || att.area === filter;
    return matchesSearch && matchesFilter;
  });

  const sortedFiltered = filteredAttorneys.sort((a, b) => {
    if (asc) {
      return a[sortedBy] < b[sortedBy] ? -1 : 1;
    } else {
      return a[sortedBy] > b[sortedBy] ? -1 : 1;
    }
  });

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-8 bg-slate-950 text-slate-100 font-sans">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-12 pb-6 border-b border-slate-800">
        <div>
          <h2 className="text-2xl sm:text-3xl font-semibold tracking-tight text-slate-100 flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-indigo-400" /> Meet Our Legal Team
          </h2>
          <p className="text-slate-400 mt-2 text-sm max-w-md">
            Discover the expertise behind our successful law firm. Connect with attorneys who specialize in your industry.
          </p>
        </div>
        <div className="flex gap-4">
          <div className="relative inline-flex items-center gap-2">
            <Search className="w-4 h-4 text-slate-400" />
            <input 
              type="text" 
              placeholder="Search by name or area"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="bg-slate-900 border border-slate-800 text-slate-100 py-2 px-4 rounded-full placeholder:text-slate-500 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
          </div>
          <select 
            value={filter}
            onChange={handleFilter}
            className="bg-slate-900 border border-slate-800 text-slate-100 py-2 px-4 rounded-full text-sm font-medium outline-none transition-all"
          >
            <option value="All">All Practice Areas</option>
            <option value="Corporate & M&A">Corporate & M&A</option>
            <option value="Intellectual Property">Intellectual Property</option>
            <option value="Employment Law">Employment Law</option>
          </select>
        </div>
      </div>

      {/* List Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
        {sortedFiltered.map((att) => {
          const { id, name, title, area, bio, office, rate, badge, verified } = att;
          return (
            <div 
              key={id}
              className="group relative bg-slate-900 border border-slate-800 rounded-2xl p-6 hover:shadow-2xl transition-all duration-300 hover:scale-[1.02]"
            >
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/20 to-purple-500/10 backdrop-blur-xl rounded-2xl pointer-events-none group-hover:from-indigo-500/40 group-hover:to-purple-500/20" />
              <div className="relative z-10 flex items-start justify-between gap-4 mb-6">
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-2">
                    {name.split(' ').map((n, i) => (
                      <div 
                        key={i}
                        className="w-5 h-5 bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 rounded-full flex items-center justify-center font-bold shadow-inner transition-colors duration-300 group-hover:bg-indigo-600/20 group-hover:text-indigo-300"
                      >
                        {n.charAt(0)}
                      </div>
                    ))}
                  </div>
                  <h3 className="text-xl font-semibold text-slate-100 group-hover:text-white">{name}</h3>
                </div>
                {verified && (
                  <div className="p-2 rounded-lg bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 text-xs font-medium shadow-inner">
                    <UserCheck className="w-4 h-4" /> Verified Expert
                  </div>
                )}
              </div>
              <p className="text-slate-400 text-sm mt-4">{title}</p>
              <p className="text-slate-400 text-sm mt-2">{area}</p>
              <div className="flex items-center justify-between mt-8">
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4 text-slate-400" />
                  <span>{bio}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-slate-400" />
                  <span>{rate}</span>
                </div>
              </div>
              <div className="mt-8">
                <div className="flex items-center gap-2">
                  <Mail className="w-4 h-4 text-slate-400" />
                  <span>{`{${name.split(' ')[0].toLowerCase()}}@thebusinesslawfirm.com`}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Phone className="w-4 h-4 text-slate-400" />
                  <span>(415) 555-1234</span>
                </div>
              </div>
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-full h-1 bg-slate-800" />
              </div>
              <div className="absolute bottom-0 left-0 right-0 p-4 bg-slate-950 border-t border-slate-800">
                <button 
                  className="w-full px-6 py-3 text-sm font-semibold rounded-xl bg-white/5 text-slate-200 hover:bg-white/10 transition-colors duration-200"
                >
                  Book a Call
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Sorting & Filter Controls */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1">
            {['name', 'area', 'rate'].map((field) => {
              const isActive = sortedBy === field && !asc;
              const isReverse = sortedBy === field && asc;
              const icon = isReverse ? '▲' : '▼';
              return (
                <button 
                  key={field}
                  onClick={() => handleSort(field)}
                  className={`py-2 px-3 rounded-lg border border-slate-800 bg-slate-900 text-slate-400 hover:text-slate-100 transition-colors duration-200 ${
                    sortedBy === field && 'bg-indigo-950 text-indigo-300 border-indigo-900'
                  }`}
                >
                  {icon} {field.toUpperCase()}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

